function buildPosts(): SeedPost[] {
  const posts: SeedPost[] = [];
  let index = 0;
  const now = Date.now();

  // Phase A: Standalone topic posts (~55 posts)
  for (const t of TOPICS) {
    const sectionContent = t.sections.map(s =>
      `## ${s.heading}\n\n${paragraph(s.heading, s.detail)}`
    ).join("\n\n");
    const faqContent = faqSection(t.faqs);
    const content = `# ${t.title}\n\n${sectionContent}\n\n${faqContent}\n\n${ctaBlock()}`;

    posts.push({
      title: t.title,
      slug: t.slug,
      excerpt: t.metaDesc,
      content,
      category: t.category,
      featured: t.featured || false,
      is_published: true,
      published_at: new Date(now - index * 3600000).toISOString(),
      keywords: t.keywords,
      meta_description: t.metaDesc.slice(0, 160),
    });
    index++;
  }

  // Phase B: City-targeted posts (6 templates × ~57 cities = ~342 posts)
  for (const city of MAJOR_CITIES) {
    const citySlug = slugify(city);
    for (const tmpl of CITY_TEMPLATES) {
      const title = tmpl.titleTemplate.replace(/\{\{city\}\}/g, city);
      const slug = tmpl.slugTemplate.replace(/\{\{city-slug\}\}/g, citySlug);
      const keywords = tmpl.keywordsTemplate.replace(/\{\{city\}\}/g, city);
      const metaDesc = tmpl.metaDescTemplate.replace(/\{\{city\}\}/g, city);

      const sectionContent = tmpl.sections.map(s => {
        const heading = s.heading.replace(/\{\{city\}\}/g, city);
        const detail = s.detailTemplate.replace(/\{\{city\}\}/g, city);
        return `## ${heading}\n\n${paragraph(heading, detail)}`;
      }).join("\n\n");

      const faqContent = faqSection(tmpl.faqs.map(f => ({
        q: f.q.replace(/\{\{city\}\}/g, city),
        a: f.aTemplate.replace(/\{\{city\}\}/g, city),
      })));

      const content = `# ${title}\n\n${sectionContent}\n\n${faqContent}\n\n${ctaBlock()}`;

      posts.push({
        title,
        slug,
        excerpt: metaDesc,
        content,
        category: tmpl.category,
        featured: false,
        is_published: true,
        published_at: new Date(now - index * 1800000).toISOString(),
        keywords,
        meta_description: metaDesc.slice(0, 160),
      });
      index++;
    }
  }

  return posts;
}

async function updateExisting2025Posts(supabase: any) {
  console.log("\n🔄 Phase 1: Updating existing blog posts with '2025' → '2026'...\n");
  
  const { data: oldPosts, error } = await supabase
    .from("blog_posts")
    .select("id, title, slug, content, excerpt, keywords, meta_description")
    .or("title.ilike.%2025%,slug.ilike.%2025%,content.ilike.%2025%,excerpt.ilike.%2025%,keywords.ilike.%2025%,meta_description.ilike.%2025%");

  if (error) {
    console.error("❌ Error fetching 2025 posts:", error.message);
    return 0;
  }

  if (!oldPosts || oldPosts.length === 0) {
    console.log("✅ No posts with '2025' found — already up to date.");
    return 0;
  }

  console.log(`   Found ${oldPosts.length} posts with '2025' references. Updating...`);
  let updated = 0;

  for (const post of oldPosts) {
    const updates: Record<string, string> = {};
    if (post.title && post.title.includes("2025")) updates.title = post.title.replace(/2025/g, "2026");
    if (post.slug && post.slug.includes("2025")) updates.slug = post.slug.replace(/2025/g, "2026");
    if (post.content && post.content.includes("2025")) updates.content = post.content.replace(/2025/g, "2026");
    if (post.excerpt && post.excerpt.includes("2025")) updates.excerpt = post.excerpt.replace(/2025/g, "2026");
    if (post.keywords && post.keywords.includes("2025")) updates.keywords = post.keywords.replace(/2025/g, "2026");
    if (post.meta_description && post.meta_description.includes("2025")) updates.meta_description = post.meta_description.replace(/2025/g, "2026");

    if (Object.keys(updates).length > 0) {
      const { error: updateErr } = await supabase
        .from("blog_posts")
        .update(updates)
        .eq("id", post.id);

      if (updateErr) {
        console.error(`   ❌ Failed to update post ${post.id}: ${updateErr.message}`);
      } else {
        updated++;
      }
    }
  }

  console.log(`   ✅ Updated ${updated}/${oldPosts.length} posts from 2025 → 2026.\n`);
  return updated;
}

async function main() {
  console.log("🚀 StreamStickPro Blog Engine: 400 New Posts + 2025→2026 Update\n");
  
  if (!SUPABASE_URL || !SUPABASE_SERVICE_KEY) {
    console.error("❌ Set VITE_SUPABASE_URL and SUPABASE_SERVICE_KEY");
    process.exit(1);
  }

  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);

  // Phase 1: Update existing 2025 posts
  await updateExisting2025Posts(supabase);

  // Phase 2: Seed new posts
  const posts = buildPosts();
  console.log(`📝 Phase 2: Seeding ${posts.length} NEW blog posts...\n`);
  
  let successCount = 0, errorCount = 0;
  
  for (let i = 0; i < posts.length; i += BATCH_SIZE) {
    const batch = posts.slice(i, i + BATCH_SIZE);
    const { error } = await supabase.from("blog_posts").upsert(batch, { onConflict: "slug" });
    
    if (error) {
      for (const p of batch) {
        const { error: e } = await supabase.from("blog_posts").upsert(p, { onConflict: "slug" });
        if (e) {
          console.error(`   ❌ ${p.slug}: ${e.message}`);
          errorCount++;
        } else {
          successCount++;
        }
      }
    } else {
      successCount += batch.length;
    }
    
    console.log(`   ${Math.min(i + BATCH_SIZE, posts.length)}/${posts.length} processed`);
  }

  console.log(`\n✅ Done! Success: ${successCount}, Errors: ${errorCount}`);
  
  const { count } = await supabase
    .from("blog_posts")
    .select("slug", { count: "exact", head: true })
    .eq("is_published", true);
  
  console.log(`📊 Total published posts in DB: ${count ?? "?"}`);
}

main().catch(console.error);
